import React from 'react';

export default class KeepAlive extends React.Component {
  state = { mounted: false };

  componentDidMount() {
    this.setState({ mounted: true });
  }

  render() {
    if (!this.state.mounted) return null;
    return (
      <div className={this.props.active ? '' : 'hidden'}>
        {this.props.children}
      </div>
    );
  }
}
